def ring_to_multipolygon(ring):
    if isinstance(ring, str):
        ring = json.loads(ring)
    points = [tuple(map(float, p[:2])) for p in ring]
    if points and points[0] != points[-1]:
        points.append(points[0])  # GEOS needs a closed ring
    polygon = Polygon(points, srid=4326)
    return MultiPolygon(polygon, srid=4326) if polygon.valid else None


